try:
    import numpy as np
    from scipy import stats as sp_stats
    skip_cols = ['order_id']
    anom_cols = [c for c in ['revenue', 'units', 'discount', 'marketing_spend'] if c not in skip_cols]
    total_anomalies = 0
    for col in anom_cols:
        if total_anomalies >= 25:
            break
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1e-9)
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        Q1, Q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        IQR = Q3 - Q1
        lo3, hi3 = Q1 - 3*IQR, Q3 + 3*IQR
        lo4, hi4 = Q1 - 4*IQR, Q3 + 4*IQR
        lo5, hi5 = Q1 - 5*IQR, Q3 + 5*IQR
        mask = (s_t < lo3) | (s_t > hi3)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else lo3
            orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else hi3
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{orig_lo:.2f}, {orig_hi:.2f}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-boundary flags exceed 5% of rows, column skipped for individual anomalies'
            })
            total_anomalies += 1
            continue
        flagged_idx = s_t[mask].index
        for idx in flagged_idx:
            if total_anomalies >= 25:
                break
            val_t = s_t.loc[idx]
            val_orig = float(df.loc[idx, col])
            orig_lo = float(np.expm1(lo3) - shift) if abs(skew) > 2 else lo3
            orig_hi = float(np.expm1(hi3) - shift) if abs(skew) > 2 else hi3
            if val_t > hi5 or val_t < lo5:
                sev = 'critical'
            elif val_t > hi4 or val_t < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            exp_range = f'[{orig_lo:.2f}, {orig_hi:.2f}]'
            result['anomalies'].append({
                'column': col, 'row_index': int(idx), 'value': val_orig,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {val_orig} lies outside expected range {exp_range}'
            })
            total_anomalies += 1
except Exception:
    pass

