    anomaly_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    total_anomalies = 0
    for col in anomaly_cols:
        if total_anomalies >= 25:
            break
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1e-9)
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
            shift = 0.0
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (vals < lo3) | (vals > hi3)
        flagged_frac = mask.sum() / len(s)
        if flagged_frac > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(s.quantile(0.25)):.4g}, {float(s.quantile(0.75)):.4g}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        flagged_idx = vals[mask].index
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = float(lo3), float(hi3)
        exp_range = f'[{orig_lo:.4g}, {orig_hi:.4g}]'
        for idx in flagged_idx:
            if total_anomalies >= 25:
                break
            raw_val = float(df.loc[idx, col])
            tv = vals.loc[idx]
            if tv > hi5 or tv < lo5:
                sev = 'critical'
            elif tv > hi4 or tv < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            result['anomalies'].append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw_val:.4g} lies outside expected range {exp_range}'
            })
            total_anomalies += 1
