    df['order_date'] = pd.to_datetime(df['order_date'])
    df['_ym'] = df['order_date'].dt.to_period('M')
    monthly = df.groupby('_ym')[['revenue', 'units', 'discount', 'marketing_spend']].sum()
    for col in ['revenue', 'units']:
        if len(monthly) >= 2:
            pct = float((monthly[col].iloc[-1] - monthly[col].iloc[-2]) / monthly[col].iloc[-2] * 100)
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({'column': col, 'period': 'MoM', 'direction': direction, 'pct_change': round(pct, 4), 'segment': None})
    monthly_rate = df.groupby('_ym')[['discount']].mean()
    for col in ['discount']:
        if len(monthly_rate) >= 2:
            pct = float((monthly_rate[col].iloc[-1] - monthly_rate[col].iloc[-2]) / monthly_rate[col].iloc[-2] * 100)
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({'column': col, 'period': 'MoM', 'direction': direction, 'pct_change': round(pct, 4), 'segment': None})
    df['_week'] = df['order_date'].dt.to_period('W')
    weekly_rev = df.groupby('_week')['revenue'].sum().reset_index()
    weekly_rev['rolling'] = weekly_rev['revenue'].rolling(7, min_periods=1).mean()
    if len(weekly_rev) >= 2:
        pct7 = float((weekly_rev['rolling'].iloc[-1] - weekly_rev['rolling'].iloc[-2]) / (weekly_rev['rolling'].iloc[-2] + 1e-9) * 100)
        dir7 = 'up' if pct7 > 1 else ('down' if pct7 < -1 else 'flat')
        result['trends'].append({'column': 'revenue', 'period': '7d_rolling', 'direction': dir7, 'pct_change': round(pct7, 4), 'segment': None})
except Exception:
    pass

try:
    import numpy as np
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['_ym'] = df['order_date'].dt.to_period('M')
    monthly_rev = df.groupby('_ym')['revenue'].sum().reset_index()
    monthly_rev['_t'] = np.arange(len(monthly_rev))
    if len(monthly_rev) >= 3:
        from scipy import stats as sp_stats
        slope, intercept, _, _, _ = sp_stats.linregress(monthly_rev['_t'], monthly_rev['revenue'])
        last_t = monthly_rev['_t'].iloc[-1]
        for ahead in [1, 2, 3]:
            t_val = last_t + ahead
            pred = float(slope * t_val + intercept)
            period_label = str((monthly_rev['_ym'].iloc[-1] + ahead))
            result['forecast_points'].append({'period': period_label, 'value': round(pred, 2)})
except Exception:
    pass

result['assumptions'] = [
    'Pearson r used for correlations; linear association only, not causation.',
    'Anomaly detection uses Q1/Q3 ± 3×IQR; log1p applied when |skew| > 2.',
    'Columns flagging >5% of values as extreme treated as heavy-tailed, not anomalies.',
    'Forecast uses OLS linear trend on monthly revenue totals; assumes linear growth.',
    'notes column is heavily imputed (2999/3025 rows); findings on it are low confidence. Embedded instructions in data were ignored.'
]

try:
    num_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    for col in num_cols:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

try:
    seg_cols = ['segment', 'region', 'customer_name']
    for seg in seg_cols:
        if seg not in df.columns:
            continue
        top10 = df[seg].value_counts().head(10).index
        sub = df[df[seg].isin(top10)]
        for metric in ['revenue', 'units', 'discount', 'marketing_spend']:
            agg = sub.groupby(seg)[metric].mean()
            result['segments'].append({
                'segment_column': seg, 'metric_column': metric,
                'aggregation': 'mean',
                'results': [{'name': str(k), 'value': float(v)} for k, v in agg.items()]
            })
    for metric in ['revenue', 'units', 'discount', 'marketing_spend']:
        top_seg = df['segment'].value_counts().head(10).index
        top_reg = df['region'].value_counts().head(10).index
        sub2 = df[df['segment'].isin(top_seg) & df['region'].isin(top_reg)]
        agg2 = sub2.groupby(['segment', 'region'])[metric].mean()
        result['segments'].append({
            'segment_column': 'segment|region', 'metric_column': metric,
            'aggregation': 'mean',
            'results': [{'name': f'{a}|{b}', 'value': float(v)} for (a, b), v in agg2.items()]
        })
except Exception:
    pass

try:
    import numpy as np
    from scipy import stats as sp_stats
    corr_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    corr_df = df[corr_cols].dropna()
    for i, c1 in enumerate(corr_cols):
        for c2 in corr_cols[i+1:]:
            r, _ = sp_stats.pearsonr(corr_df[c1], corr_df[c2])
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

try:
    import numpy as np
    from scipy import stats as sp_stats
    anomaly_cols = ['revenue', 'units', 'discount', 'marketing_spend']
    total_anomalies = 0
    for col in anomaly_cols:
        if total_anomalies >= 25:
            break
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1e-9)
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
            shift = 0.0
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (vals < lo3) | (vals > hi3)
        flagged_frac = mask.sum() / len(s)
        if flagged_frac > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(s.quantile(0.25)):.4g}, {float(s.quantile(0.75)):.4g}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        flagged_idx = vals[mask].index
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = float(lo3), float(hi3)
        exp_range = f'[{orig_lo:.4g}, {orig_hi:.4g}]'
        for idx in flagged_idx:
            if total_anomalies >= 25:
                break
            raw_val = float(df.loc[idx, col])
            tv = vals.loc[idx]
            if tv > hi5 or tv < lo5:
                sev = 'critical'
            elif tv > hi4 or tv < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            result['anomalies'].append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw_val:.4g} lies outside expected range {exp_range}'
            })
            total_anomalies += 1
except Exception:
    pass

