try:
    import numpy as np
    from scipy import stats as sp_stats
    anomaly_records = []
    hard_cap = 25
    skip_cols = ['order_id']
    for col in ['revenue', 'units', 'discount', 'marketing_spend']:
        if col in skip_cols:
            continue
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -s.min() if s.min() < 0 else 0
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_ext = q1 - 3 * iqr
        hi_ext = q3 + 3 * iqr
        mask = (s_t < lo_ext) | (s_t > hi_ext)
        flagged_frac = mask.sum() / len(s_t)
        if flagged_frac > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_ext) - shift)
            hi_orig = float(np.expm1(hi_ext) - shift)
        else:
            lo_orig = float(lo_ext)
            hi_orig = float(hi_ext)
        exp_range = f'[{lo_orig:.4g}, {hi_orig:.4g}]'
        flagged_idx = s_t[mask].index
        lo4 = q1 - 4 * iqr; hi4 = q3 + 4 * iqr
        lo5 = q1 - 5 * iqr; hi5 = q3 + 5 * iqr
        for idx in flagged_idx:
            if len(anomaly_records) >= hard_cap:
                break
            val_t = s_t[idx]
            val_orig = float(df.loc[idx, col])
            if val_t > hi5 or val_t < lo5:
                sev = 'critical'
            elif val_t > hi4 or val_t < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': val_orig,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {val_orig} lies outside expected range {exp_range}'
            })
        if len(anomaly_records) >= hard_cap:
            break
    result['anomalies'].extend(anomaly_records)
except Exception:
    pass

