try:
    import numpy as np
    from scipy import stats as sp_stats
    skip_cols = {'order_id'}
    anomaly_records = []
    for col in ['revenue', 'units', 'discount', 'marketing_spend']:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1e-6)
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo, hi = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_t < lo) | (s_t > hi)
        flagged_frac = mask.sum() / len(s_t)
        if flagged_frac > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(np.expm1(lo)-shift):.2f}, {float(np.expm1(hi)-shift):.2f}]' if abs(skew) > 2 else f'[{lo:.2f}, {hi:.2f}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-outlier rule flags >{flagged_frac*100:.1f}% of values, column skipped for individual anomalies'
            })
            continue
        flagged_idx = s_t[mask].index.tolist()
        for idx in flagged_idx:
            orig_val = float(df.loc[idx, col])
            t_val = float(s_t.loc[idx])
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo) - shift)
                hi_orig = float(np.expm1(hi) - shift)
            else:
                lo_orig, hi_orig = lo, hi
            exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
            if t_val > hi5 or t_val < lo5:
                sev = 'critical'
            elif t_val > hi4 or t_val < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {orig_val} lies outside expected range {exp_range}'
            })
    anomaly_records.sort(key=lambda x: ['low','medium','high','critical'].index(x['severity']), reverse=True)
    result['anomalies'] = anomaly_records[:25]
except Exception:
    pass

